export function mount(root){root.innerHTML='<p class="notice">Working project integration · opt-in 60-second tour of four supported stations. Use Start inside the journey, then Pause, Skip or Exit. Reduced motion uses instant station cuts.</p><iframe class="tour-frame" title="60-second forest journey tour" src="/explore/?tour=1"></iframe>';return()=>{const frame=root.querySelector('iframe');if(frame)frame.src='about:blank';root.replaceChildren();};}
